package com.bank.virtual;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class VirtualThreadsTest {

    // ═══ Virtual thread: lightweight, millions possible ═══
    @Test
    void virtualThread_basic() throws InterruptedException {
        AtomicReference<String> result = new AtomicReference<>();
        Thread vt = Thread.ofVirtual().name("vt-1").start(() -> {
            result.set("Virtual: " + Thread.currentThread().isVirtual());
        });
        vt.join();
        assertThat(result.get()).isEqualTo("Virtual: true");
    }

    // ═══ 10K virtual threads — trivial! ═══
    @Test
    void tenThousand_virtualThreads() throws InterruptedException {
        int count = 10_000;
        AtomicInteger completed = new AtomicInteger(0);
        CountDownLatch latch = new CountDownLatch(count);

        long start = System.currentTimeMillis();
        try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < count; i++) {
                executor.submit(() -> {
                    try { Thread.sleep(100); } catch (InterruptedException e) { }
                    completed.incrementAndGet();
                    latch.countDown();
                });
            }
            latch.await(30, TimeUnit.SECONDS);
        }
        long elapsed = System.currentTimeMillis() - start;

        assertThat(completed.get()).isEqualTo(count);
        System.out.println("10K virtual threads (100ms sleep each): " + elapsed + "ms");
        // ~100-200ms! All 10K run concurrently!
        // Platform threads: 10K × 1MB stack = 10GB! OOM!
    }

    // ═══ CF still better for composition ═══
    @Test
    void cf_stillBetterForComposition() throws Exception {
        CompletableFuture<Integer> total = CompletableFuture
            .supplyAsync(() -> { sleep(100); return 100000; })
            .thenCombine(
                CompletableFuture.supplyAsync(() -> { sleep(100); return 250000; }),
                Integer::sum)
            .orTimeout(5, TimeUnit.SECONDS);  // timeout!

        assertThat(total.get()).isEqualTo(350000);
        // Clean composition + timeout — harder with raw virtual threads!
    }

    // ═══ Virtual threads: isVirtual() ═══
    @Test
    void detectVirtualThread() throws InterruptedException {
        Thread platform = new Thread(() -> {
            assertThat(Thread.currentThread().isVirtual()).isFalse();
        });
        platform.start(); platform.join();

        Thread virtual = Thread.ofVirtual().start(() -> {
            assertThat(Thread.currentThread().isVirtual()).isTrue();
        });
        virtual.join();
    }

    void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) {} }
}
